begin;create extension if not exists pgtap with schema extensions;select plan(24);
select has_table('public','match_snapshots','immutable match snapshots exist');
select has_table('public','competition_action_requests','idempotency ledger exists');
select has_table('public','group_advancement_results','group advancement is persisted');
select has_view('public','public_competition_rankings','configured ranking projection exists');
select has_function('public','advance_groups_to_knockout',array['uuid','timestamp with time zone','integer'],'protected group advancement exists');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);set local role authenticated;
select lives_ok($$select public.configure_competition('10000000-0000-4000-8000-000000000001','groups')$$,'groups configuration accepted');
select lives_ok($$select public.create_competition_group('10000000-0000-4000-8000-000000000001','Four',array['40000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000002','40000000-0000-4000-8000-000000000003','40000000-0000-4000-8000-000000000004']::uuid[])$$,'four-team group created');
select is(public.generate_competition_schedule('10000000-0000-4000-8000-000000000001',now(),60),6,'four-team group creates six fixtures');
reset role;
select is((select count(*)from public.matches where team_a_id=team_b_id),0::bigint,'group has no self match');
select is((select count(*)from(select least(team_a_id,team_b_id),greatest(team_a_id,team_b_id),count(*)from public.matches group by 1,2 having count(*)>1)x),0::bigint,'group has no duplicate pair');
select is((select count(*)from public.matches m join public.competition_group_teams a on a.team_id=m.team_a_id join public.competition_group_teams b on b.team_id=m.team_b_id where a.group_id<>b.group_id),0::bigint,'group schedule has no cross-group fixture');
delete from public.matches;delete from public.competition_settings;delete from public.competition_stages;
insert into public.competition_settings(tournament_id,format,configured_by)values('10000000-0000-4000-8000-000000000001','single_elimination','00000000-0000-4000-8000-000000000001');
select is(private.build_single_elimination('10000000-0000-4000-8000-000000000001',array['40000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000002','40000000-0000-4000-8000-000000000003','40000000-0000-4000-8000-000000000004']::uuid[],now(),60),3,'four-team bracket has n minus one matches');
select is((select count(*)from public.matches where team_a_id is null and team_b_id is null),1::bigint,'only future final begins empty');
delete from public.matches;delete from public.competition_stages;
select is(private.build_single_elimination('10000000-0000-4000-8000-000000000001',array(select id from public.teams order by id limit 6),now(),60),5,'six-team bracket has n minus one matches');
select is((select count(*)from public.matches where round_number=1),2::bigint,'six-team bracket creates two played first-round matches');
select is((select count(*)from public.matches where round_number=2 and (team_a_id is not null or team_b_id is not null)),1::bigint,'byes populate trusted downstream semifinal slots');
select is((select count(*)from public.audit_events where event_type='BRACKET_BYE_ADVANCED'),2::bigint,'each bye advancement audited once');
select is((select count(*)from public.matches where team_a_id=team_b_id and team_a_id is not null),0::bigint,'bye never duplicates a participant');
delete from public.matches;
delete from public.competition_stages;insert into public.teams(id,tournament_id,name,short_tag,captain_user_id,starting_credits,credits_remaining,captain_mmr,current_team_mmr,max_roster_size)select ('41000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'10000000-0000-4000-8000-000000000001','Extra '||n,'E'||n,('00000000-0000-4000-8000-'||lpad((n+6)::text,12,'0'))::uuid,1000,1000,2000,2000,5 from generate_series(1,10)n;
select is(private.build_single_elimination('10000000-0000-4000-8000-000000000001',array(select id from public.teams order by id limit 8),now(),60),7,'eight-team bracket has seven matches');
delete from public.matches;
delete from public.competition_stages;
select is(private.build_single_elimination('10000000-0000-4000-8000-000000000001',array(select id from public.teams order by id limit 12),now(),60),11,'twelve-team bracket has eleven matches');
delete from public.matches;
delete from public.competition_stages;
select is(private.build_single_elimination('10000000-0000-4000-8000-000000000001',array(select id from public.teams order by id limit 16),now(),60),15,'sixteen-team bracket has fifteen matches');
select is((select count(*)from public.matches where next_match_id is not null),14::bigint,'every non-final match persists a downstream route');
select is((select count(*)from public.matches where team_a_id=team_b_id and team_a_id is not null),0::bigint,'large bracket never duplicates team slots');
select ok(not exists(select 1 from information_schema.columns where table_schema='public'and table_name='public_matches'and column_name in('lobby_password','forfeit_reason')),'public match projection remains private-field safe');
select * from finish();rollback;
